class Solution:
    def countPalindromes(self, s: str) -> int:
        from itertools import combinations
        MOD = 10**9 + 7
        ans = 0
        for combo in combinations(range(len(s)), 5):
            t = ''.join(s[i] for i in combo)
            if t == t[::-1]:
                ans += 1
        return ans % MOD

