class Solution {
public:
    int countPalindromes(string s) {
        const int MOD = 1e9 + 7;
        int n = s.size(), ans = 0;
        for (int a = 0; a < n; a++)
          for (int b = a + 1; b < n; b++)
            for (int c = b + 1; c < n; c++)
              for (int d = c + 1; d < n; d++)
                for (int e = d + 1; e < n; e++)
                  if (s[a] == s[e] && s[b] == s[d]) ans = (ans + 1) % MOD;
        return ans;
    }
};

